import com.onebytelabs.zlplay.audio.*;
import com.onebytelabs.zlplay.project.*;
import java.util.*;
public final class RoutingTest {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static PcmTrack constant(String name,float v){float[] s=new float[96000];Arrays.fill(s,v);return new PcmTrack(name,48000,1,s);}
 public static void main(String[] args){DemoMixer m=new DemoMixer();m.load(new PcmTrack[]{constant("Piano",.25f),constant("Click",.125f)});m.setGain(0,1);m.setGain(1,1);m.setRoute(4,0);m.setRoute(1,1);m.setMasterLevel(0);m.play();float[] out=new float[9600];m.renderRouted(out,4800,2);check(Math.abs(out[9598]-.25)<.001&&Math.abs(out[9599]-.125)<.001,"VS and Click isolated in outputs 1 and 2, bypassing Master");check(m.meter(0)>.24&&m.meter(-2)>.12,"Meters reflect source audio");m.setMuted(-5,true);m.renderRouted(out,4800,2);check(out[9598]==0&&out[9599]>.12,"Bus mute isolates its output");m.setMuted(-5,false);m.setSolo(0,true);m.renderRouted(out,4800,2);check(out[9598]>.24&&out[9599]==0,"Track solo silences other tracks");m.setSolo(0,false);m.setRoute(4,-1);m.setRoute(1,-1);m.setMasterLevel(1);m.setMuted(1,true);m.setChannelPan(0,-1);m.render(out,4800);check(out[9598]>.24&&out[9599]==0,"Track pan reaches stereo output");m.setMuted(0,true);m.render(out,4800);check(out[9598]==0&&out[9599]==0,"Track mute is independent of fader gain");m.setMuted(0,false);check(m.getGain(0)==1,"Unmute preserves gain");m.setRoute(4,106);m.setRoute(1,2);float[] multi=new float[8*512];m.renderRouted(multi,512,8);check(multi[multi.length-2]>.24&&multi[multi.length-8]==0,"Eight-channel PCM preserves destination channel index");ProjectSpec spec=new ProjectSpec();spec.duration=2;for(String name:new String[]{"Piano","Click"}){ProjectSpec.Track t=new ProjectSpec.Track();t.name=name;spec.tracks.add(t);}spec.tracks.get(0).mute=true;m.configureProject(spec);check(m.isMuted(0),"Imported mute remains a switch");m.setMuted(0,false);check(m.getGain(0)==1&&!m.isMuted(0),"Unmuting retains original fader level");m.setTrackRoute(0,2);m.setVsLevel(0);float[] direct=new float[512*4];m.renderRouted(direct,512,4);check(direct[direct.length-2]>.12,"Individual track route bypasses VS and preserves its gain");m.setPadLevel(2);check(m.getPadLevel()==2,"Pad unity/headroom matches other faders");System.out.println("PASS: channel routing, direct bus bypass, meters, mute, solo, pan, unmute gain and 8-channel PCM");}
}
